import random
import sys
sys.path.insert(0, '.')
# inline the dinuc_shuffle
def dinuc_shuffle(seq, rng):
    n = len(seq)
    if n < 4:
        return seq
    edges = {b: [] for b in 'ACGT'}
    for i in range(n - 1):
        a, b = seq[i], seq[i + 1]
        if a in edges and b in 'ACGT':
            edges[a].append(b)
    for _ in range(50):
        for k in edges:
            rng.shuffle(edges[k])
        start = seq[0]
        path = [start]
        ptrs = {k: 0 for k in edges}
        cur = start
        ok = True
        for _step in range(n - 1):
            if ptrs[cur] >= len(edges[cur]):
                ok = False
                break
            nxt = edges[cur][ptrs[cur]]
            ptrs[cur] += 1
            path.append(nxt)
            cur = nxt
        if ok and len(path) == n:
            return ''.join(path)
    return seq

def dinucs(s):
    d = {}
    for i in range(len(s)-1):
        d[s[i:i+2]] = d.get(s[i:i+2], 0) + 1
    return d

rng = random.Random(42)
import numpy as np
nprng = np.random.default_rng(42)
n_ok = 0
n_total = 200
n_unchanged = 0
for _ in range(n_total):
    seq = ''.join(nprng.choice(list('ACGT'), 200))
    sh = dinuc_shuffle(seq, rng)
    if dinucs(seq) == dinucs(sh):
        n_ok += 1
    if seq == sh:
        n_unchanged += 1
print(f'Preserved dinucs in {n_ok}/{n_total}; unchanged: {n_unchanged}')
